export const EVENTS = Object.entries(GROUPS).flatMap(([category,names])=>names.map(name=>({name,category,special:['Personal Care','Life Support Skills','Interviewing Skills','Speaking Skills'].includes(name)})));
export const RANKS = ['Iron','Bronze','Silver','Gold','Platinum','Diamond','Ascendant','Immortal','Radiant'];
// Lowest rating (average ranked test score) for each rank. Each band below Radiant splits into I · II · III.
export const RANK_FLOORS = [0,40,50,60,70,78,85,91,96];
export function rankFor(rating){
 if(rating===null||rating===undefined)return null;
 let i=RANK_FLOORS.length-1;while(i>0&&rating<RANK_FLOORS[i])i--;
 if(i===RANKS.length-1)return {tier:RANKS[i],index:i,division:'',label:RANKS[i]};
 const lo=RANK_FLOORS[i],hi=RANK_FLOORS[i+1],d=Math.min(2,Math.floor(3*(rating-lo)/(hi-lo)));
 return {tier:RANKS[i],index:i,division:['I','II','III'][d],label:RANKS[i]+' '+['I','II','III'][d]};
}
